using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    cin >> a >> b;

    long long result = 0;

    while (a > 0 && b > 0 && (a != 1 || b != 1)) {
        if (a > b) {
            a -= 2;
            ++b;
        } else {
            b -= 2;
            ++a;
        }
        ++result;
    }

    cout << result;
    return 0;
}

